// Standardize job data from RSS sources with proper user_id
const standardizedJobs = [];

// Get user_id from environment or workflow settings
const userId = process.env.USER_ID || $workflow.settings?.userId;
if (!userId) {
  throw new Error('USER_ID must be set in environment variables or workflow settings');
}

for (const item of $input.all()) {
  try {
    // Extract company from title (Indeed format: "Job Title at Company in Location")
    let company = 'Unknown';
    let location = 'Remote';
    let cleanTitle = item.json.title || 'Unknown Role';

    // Parse Indeed RSS format
    const titleMatch = cleanTitle.match(/(.+?)\s+at\s+(.+?)\s+in\s+(.+)$/);
    if (titleMatch) {
      cleanTitle = titleMatch[1].trim();
      company = titleMatch[2].trim();
      location = titleMatch[3].trim();
    }

    // Determine source
    let source = 'Unknown';
    if (item.json.link && item.json.link.includes('indeed.com')) {
      source = 'Indeed RSS';
    }

    // Create standardized job object
    const standardJob = {
      user_id: userId,
      title: cleanTitle,
      company: company,
      location: location,
      url: item.json.link || item.json.guid || '',
      description: item.json.contentSnippet || item.json.description || item.json.content || '',
      source: source,
      published: item.json.pubDate || item.json.isoDate || new Date().toISOString(),
      rawData: {
        originalTitle: item.json.title,
        guid: item.json.guid,
        categories: item.json.categories,
        creator: item.json.creator
      }
    };

    // Quality checks
    if (standardJob.url && standardJob.title && standardJob.company !== 'Unknown') {
      standardizedJobs.push({ json: standardJob });
    } else {
      console.log('Skipping low-quality job:', standardJob.title);
    }

  } catch (error) {
    console.error('Error processing job:', error, item.json);
  }
}

console.log(`Processed ${$input.all().length} raw items into ${standardizedJobs.length} standardized jobs`);

return standardizedJobs;

// Parse duplicate check response and filter
const response = $input.first().json;
const jobData = $('Standardize Job Data').item.json;

// Parse RPC response (Supabase returns array with function result)
let isDuplicate = false;
if (Array.isArray(response) && response.length > 0) {
  isDuplicate = response[0] === true || response[0].check_job_duplicate === true;
} else if (typeof response === 'boolean') {
  isDuplicate = response;
} else if (response.check_job_duplicate !== undefined) {
  isDuplicate = response.check_job_duplicate;
}

if (isDuplicate) {
  console.log(`Duplicate job found: ${jobData.title} at ${jobData.company}`);
  return {
    json: {
      ...jobData,
      skipReason: 'duplicate',
      processed: true
    }
  };
} else {
  console.log(`New job: ${jobData.title} at ${jobData.company}`);
  return {
    json: {
      ...jobData,
      skipReason: null,
      processed: false
    }
  };
}

// Parse AI scoring response and prepare for database
const aiResponse = $input.first().json;
const jobData = $('Not Duplicate').first().json;

// Get the actual AI response text - check different possible paths
let aiText = '';
if (aiResponse.message && aiResponse.message.content) {
  aiText = aiResponse.message.content.trim();
} else if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  aiText = aiResponse.choices[0].message.content.trim();
} else if (typeof aiResponse === 'string') {
  aiText = aiResponse.trim();
} else {
  console.error('Unexpected AI response format:', aiResponse);
  aiText = '';
}

let aiResult;
if (aiText) {
  try {
    // Clean the response - sometimes GPT adds markdown formatting
    const cleanedText = aiText.replace(/```json
?|```/g, '').trim();
    aiResult = JSON.parse(cleanedText);
  } catch (parseError) {
    console.error('Failed to parse AI response as JSON:', aiText);
    // Try to extract score with regex as fallback
    const scoreMatch = aiText.match(/"score"\s*:\s*(\d+)/);
    aiResult = {
      score: scoreMatch ? parseInt(scoreMatch[1]) : 5,
      reasoning: 'Failed to parse AI response fully',
      redFlags: 'Parsing error: ' + parseError.message
    };
  }
} else {
  aiResult = {
    score: 5,
    reasoning: 'No AI response received',
    redFlags: 'AI API error'
  };
}

// Create final job object for database
const finalJob = {
  company: jobData.company,
  role: jobData.title,
  location: jobData.location,
  url: jobData.url,
  description: jobData.description,
  source: jobData.source,
  ai_match_score: Math.min(Math.max(aiResult.score || 5, 1), 10), // Clamp to 1-10
  status: 'To Review',
  user_id: jobData.user_id,
  created_at: new Date().toISOString(),

  // Store AI analysis for review
  ai_reasoning: (aiResult.reasoning || 'No reasoning provided').substring(0, 500),
  ai_red_flags: aiResult.redFlags ? aiResult.redFlags.substring(0, 500) : null
};

console.log(`Job scored: ${finalJob.role} at ${finalJob.company} - Score: ${finalJob.ai_match_score}`);

return { 
  json: {
    ...finalJob,
    stagingId: $('Save to Staging').first().json.id
  }
};
